import{_ as d,C as n,o as l,c as i,a6 as g,E as a,j as e,a as o}from"./chunks/framework.CrjICMdL.js";const c="/rb_cobot_docs_muscat/images/settings/collision-overview.avif",h="/rb_cobot_docs_muscat/images/settings/collision-out.avif",p="/rb_cobot_docs_muscat/images/settings/collision-self.avif",k=JSON.parse('{"title":"충돌 감지","description":"","frontmatter":{"title":"충돌 감지","outline":[2,3]},"headers":[],"relativePath":"manual/settings/collision-detection.md","filePath":"manual/settings/collision-detection.md","lastUpdated":1792552919000}'),b={name:"manual/settings/collision-detection.md"};function m(u,t,x,_,f,y){const r=n("DemoFrame"),s=n("ScenarioSteps");return l(),i("div",null,[t[0]||(t[0]=g('<h1 id="충돌-감지" tabindex="-1">충돌 감지 <a class="header-anchor" href="#충돌-감지" aria-label="Permalink to &quot;충돌 감지&quot;">​</a></h1><p><strong>충돌 감지</strong>는 로봇이 <strong>외부 물체와 부딪혔을 때</strong>와 <strong>로봇 팔이 자기 자신(또는 설정한 영역)에 부딪히기 전에</strong> 어떻게 반응할지 정하는 설정입니다.</p><p>이 문서에서는 <strong>설정 &gt; 일반 &gt; 충돌 감지</strong> 화면에서 다음을 해 봅니다.</p><ul><li>외부 충돌 감지를 켜고, 멈추는 방식과 둔감도 정하기</li><li>자가 충돌의 감지 거리와 모드 정하기</li><li>저장하고 값이 유지되는지 확인하기</li></ul><p>각각 따로 해 볼 수 있는 실습이 <a href="#직접-해-보기">아래</a>에 있습니다.</p><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><p>왼쪽 설정 메뉴의 <strong>일반 &gt; 충돌 감지</strong>를 누르면 나타나는 화면입니다. 아직 아무것도 바꾸지 않은 상태입니다.</p><p><img src="'+c+'" alt="충돌 감지 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>영역</th><th>역할</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td>외부 충돌 카드</td><td>외부 충돌 감지를 켜고 끄며, 충돌했을 때 멈추는 방식과 둔감도를 정합니다.</td></tr><tr><td style="text-align:center;">②</td><td>자가 충돌 카드</td><td>자가 충돌을 감지하는 거리와, 감지했을 때의 동작(모드)을 정합니다.</td></tr></tbody></table></div><p>두 카드는 각각 <strong>초기화</strong>와 <strong>저장</strong> 버튼이 따로 있습니다. 한 카드에서 저장해도 다른 카드의 값은 바뀌지 않습니다.</p><h2 id="외부-충돌-1" tabindex="-1">외부 충돌 (①) <a class="header-anchor" href="#외부-충돌-1" aria-label="Permalink to &quot;외부 충돌 (①)&quot;">​</a></h2><p>로봇이 작업 중에 사람이나 물체와 부딪히면 이를 감지해 멈추게 하는 기능입니다. 아래는 <strong>켜기/끄기</strong>를 켜고, 정지 모드를 <strong>회피 정지</strong>로, 둔감도를 50%로 고른 뒤 아직 저장하지 않은 상태입니다.</p><p><img src="'+h+'" alt="외부 충돌 카드의 구성"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">③</td><td><strong>켜기/끄기</strong></td><td>외부 충돌 감지를 켜거나 끕니다. <strong>끄면 충돌을 감지하지 않습니다.</strong></td></tr><tr><td style="text-align:center;">④</td><td><strong>정지 모드</strong></td><td>충돌을 감지했을 때 로봇이 멈추는 방식입니다. 아래에서 자세히 설명합니다. 첫 항목(동작 일시 정지)이 아닌 값을 고르면 글자가 <span class="hl-yellow">노란색</span>으로 바뀝니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>둔감도</strong></td><td>0~100% 사이를 슬라이더로 조절하고 현재 값이 오른쪽에 표시됩니다. <strong>값이 클수록 더 큰 힘이 가해져야</strong> 충돌로 판단합니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>초기화</strong></td><td>고르기만 하고 <strong>저장하지 않은 값</strong>을 저장된 값으로 되돌립니다. 화면의 값이 저장된 값과 같으면 눌리지 않습니다.</td></tr><tr><td style="text-align:center;">⑦</td><td><strong>저장</strong></td><td>현재 값을 저장합니다. <strong>저장해야 설정이 적용됩니다.</strong></td></tr></tbody></table></div><h3 id="정지-모드" tabindex="-1">정지 모드 <a class="header-anchor" href="#정지-모드" aria-label="Permalink to &quot;정지 모드&quot;">​</a></h3><table tabindex="0"><thead><tr><th>선택</th><th>동작</th></tr></thead><tbody><tr><td><strong>동작 일시 정지</strong></td><td>충돌을 감지하면 동작을 멈추고 그 상태로 있습니다. 기본값입니다.</td></tr><tr><td><strong>회피 정지</strong></td><td>충돌을 감지했을 때 로봇이 움직이는 중이면, 멈춘 뒤 회피 동작을 수행합니다. 회피 동작을 마치면 충돌 상태가 <strong>자동으로 해제</strong>됩니다.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">충돌 상태 해제</p><p>동작 일시 정지에서 멈춘 뒤에는 충돌 상태를 해제(리셋)해야 다시 움직일 수 있습니다. 해제한 직후 0.5초 동안은 충돌 감지를 잠시 쉬어, 해제하는 순간 다시 충돌로 판단하지 않도록 합니다.</p></div><h3 id="둔감도" tabindex="-1">둔감도 <a class="header-anchor" href="#둔감도" aria-label="Permalink to &quot;둔감도&quot;">​</a></h3><p>둔감도는 충돌로 판단하는 기준을 정합니다. 값이 <strong>클수록 둔감</strong>해서 웬만한 충격에는 멈추지 않고, 값이 <strong>작을수록 민감</strong>해서 약한 충격에도 멈춥니다. 너무 작게 두면 충돌이 아닌 작은 힘에도 멈출 수 있고, 너무 크게 두면 충돌을 늦게 감지할 수 있으므로 작업에 맞게 조절합니다.</p><div class="warning custom-block"><p class="custom-block-title">안전</p><p>외부 충돌 감지는 사람과 장비를 보호하는 기능입니다. 끄거나 둔감도를 크게 올리면 충돌을 감지하지 못하거나 늦게 감지할 수 있으니 주의하세요. 직접 교시 중에는 외부 충돌 감지가 동작하지 않습니다.</p></div><h2 id="자가-충돌-2" tabindex="-1">자가 충돌 (②) <a class="header-anchor" href="#자가-충돌-2" aria-label="Permalink to &quot;자가 충돌 (②)&quot;">​</a></h2><p>로봇 팔이 자기 자신이나 툴·설정한 영역과 <strong>닿기 전에</strong> 감지해 대응하는 기능입니다. 아래는 아직 아무것도 바꾸지 않은 상태입니다.</p><p><img src="'+p+'" alt="자가 충돌 카드의 구성"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">⑧</td><td><strong>감지 거리 &gt; 로봇 팔 (mm)</strong></td><td>로봇 팔의 부분끼리 이 거리 이내로 가까워지면 자가 충돌로 판단하는 거리입니다. 0 이상의 값을 mm 단위로 입력하며 소수점 셋째 자리까지 입력할 수 있습니다.</td></tr><tr><td style="text-align:center;">⑨</td><td><strong>감지 거리 &gt; 외부 (mm)</strong></td><td>로봇 팔과 <strong>툴</strong>(툴 모양을 설정한 경우), 설정한 <strong>영역</strong> 사이의 감지 거리입니다. 입력 방식은 ⑧과 같습니다.</td></tr><tr><td style="text-align:center;">⑩</td><td><strong>모드</strong></td><td>자가 충돌을 감지했을 때의 동작입니다. 아래에서 설명합니다. 첫 항목이 아닌 값을 고르면 글자가 <span class="hl-yellow">노란색</span>으로 바뀝니다.</td></tr></tbody></table></div><p>카드 위쪽의 <strong>초기화</strong>와 <strong>저장</strong>은 외부 충돌 카드와 같게 동작합니다.</p><h3 id="모드" tabindex="-1">모드 <a class="header-anchor" href="#모드" aria-label="Permalink to &quot;모드&quot;">​</a></h3><table tabindex="0"><thead><tr><th>선택</th><th>동작</th></tr></thead><tbody><tr><td><strong>자가 충돌 직전 멈춤</strong></td><td>자가 충돌이 일어나기 직전에 로봇을 멈추고 더 가까워지는 방향으로는 움직이지 않습니다. 기본값입니다.</td></tr><tr><td><strong>자가 충돌시 속도 제어</strong></td><td>자가 충돌이 감지된 동안 로봇의 속도를 줄여 0으로 만듭니다. 감지 상태가 풀리면 다시 속도가 올라갑니다.</td></tr></tbody></table><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>외부 충돌과 자가 충돌은 카드마다 저장이 따로라서 실습도 둘로 나뉩니다. 어느 쪽부터 해도 되며, 앞의 실습을 하지 않아도 시작할 수 있습니다.</p><h3 id="외부-충돌-설정하기" tabindex="-1">외부 충돌 설정하기 <a class="header-anchor" href="#외부-충돌-설정하기" aria-label="Permalink to &quot;외부 충돌 설정하기&quot;">​</a></h3><p>외부 충돌을 켜고 회피 정지로 설정한 뒤 둔감도를 바꿔 저장하는 과정입니다.</p>',31)),a(r,{id:"settings-collision-detection-external"}),t[1]||(t[1]=e("h4",{id:"사용-방법",tabindex:"-1"},[o("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),a(s,{id:"settings-collision-detection-external"}),t[2]||(t[2]=e("h3",{id:"자가-충돌-설정하기",tabindex:"-1"},[o("자가 충돌 설정하기 "),e("a",{class:"header-anchor",href:"#자가-충돌-설정하기","aria-label":'Permalink to "자가 충돌 설정하기"'},"​")],-1)),t[3]||(t[3]=e("p",null,"자가 충돌의 감지 거리를 입력하고 모드를 바꿔 저장하는 과정입니다.",-1)),a(r,{id:"settings-collision-detection-self"}),t[4]||(t[4]=e("h4",{id:"사용-방법-1",tabindex:"-1"},[o("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법-1","aria-label":'Permalink to "사용 방법"'},"​")],-1)),a(s,{id:"settings-collision-detection-self"}),t[5]||(t[5]=e("div",{class:"tip custom-block"},[e("p",{class:"custom-block-title"},"저장에 실패하면"),e("p",null,'저장하지 못하면 "Collision Threshold" 또는 "Self Collision" 오류 창이 표시되고 화면의 값은 저장되지 않습니다.')],-1))])}const q=d(b,[["render",m]]);export{k as __pageData,q as default};
